<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Ubuntu Desktop Clone</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body { height: 100%; overflow: hidden; font-family: sans-serif; }
    #desktop {
      position: relative;
      width: 100vw;
      height: 100vh;
      background: linear-gradient(to bottom right, #1e1e2f, #0d0d1a);
    }
    #taskbar {
      position: fixed;
      bottom: 0; left: 0; right: 0;
      background-color: #3c3c65;
      color: white;
      padding: 10px;
      display: flex;
      justify-content: center;
      gap: 20px;
    }
    .window {
      position: absolute;
      top: 20%; left: 40%;
      background-color: #fff;
      border-radius: 8px;
      box-shadow: 0 5px 15px rgba(0,0,0,0.3);
      display: none;
      width: 400px;
      min-height: 300px;
    }
    .window .win-header {
      background-color: #2a2a58;
      color: white;
      padding: 10px;
      position: relative;
      font-weight: bold;
      border-top-left-radius: 6px;
      border-top-right-radius: 6px;
    }
    .win-close {
      float: right;
      cursor: pointer;
      background: none;
      border: none;
      color: red;
      font-size: 18px;
    }
    #files-path { padding: 10px; font-weight: bold; }
    #file-list {
      padding: 10px;
      max-height: calc(300px - 90px);
      overflow-y: auto;
    }
    .fs-item {
      cursor: pointer;
      padding: 5px;
      border-radius: 4px;
      margin-bottom: 5px;
    }
    .fs-item:hover { background-color: #eaeaea; }
    #tabs {
      display: flex;
      gap: 2px;
      border-bottom: 1px solid #ccc;
      padding-left: 5px;
    }
    .tab {
      cursor: pointer;
      padding: 4px 8px;
      background-color: #f0f0f0;
    }
    .tab:hover { background-color: #ddd; }
    #editor {
      width: 100%;
      height: calc(300px - 70px);
      margin-top: 5px;
      padding: 10px;
      font-family: monospace;
      font-size: 14px;
      border: none;
      resize: none;
    }
  </style>
</head>
<body>
  <div id="desktop">
    <div id="taskbar">
      <button id="open-files">Files</button>
      <button id="open-notepad">Notepad</button>
    </div>

    <!-- Files App -->
    <div id="files-window" class="window">
      <div class="win-header">Files<span class="win-close">&times;</span></div>
      <div id="files-path">/</div>
      <button id="files-up">&#9650; Up</button>
      <div id="file-list"></div>
    </div>

    <!-- Notepad App -->
    <div id="notepad-window" class="window">
      <div class="win-header">Notepad<span class="win-close">&times;</span></div>
      <div id="tabs"></div>
      <button id="new-tab">&#10010; New Tab</button>
      <textarea id="editor"></textarea>
    </div>
  </div>

  <script>
    // File System Data
    const fakeFs = {
      "/": ["bin", "etc", "home", "usr", "var"],
      "/home/": { user: [] },
      "/home/user/": ["Documents", "Downloads", "Pictures"]
    };

    let currentPath = "/";
    let filesWindowOpen = false;

    // Window Management
    document.querySelectorAll(".window .win-close").forEach(btn => {
      btn.addEventListener("click", () => {
        const win = btn.closest(".window");
        win.style.display = "none";
      });
    });

    document.getElementById("open-files").addEventListener("click", () => {
      showWindow("files-window");
      if (!filesWindowOpen) {
        document.getElementById("file-list").innerHTML = "";
        renderFsItems(currentPath);
        filesWindowOpen = true;
      }
    });

    document.getElementById("open-notepad").addEventListener("click", () => {
      showWindow("notepad-window");
      loadNotepad();
    });

    function showWindow(id) {
      document.querySelectorAll(".window").forEach(w => w.style.display = "none");
      document.getElementById(id).style.display = "block";
    }

    // Files App Logic
    function renderFsItems(path) {
      const dirList = document.getElementById("file-list");
      const items = getDirContents(path);
      dirList.innerHTML = "";
      items.forEach(item => {
        const el = document.createElement("div");
        el.className = "fs-item";
        el.textContent = item;
        if (isFolder(path, item)) {
          el.addEventListener("dblclick", () => navigateTo(path + item + "/"));
        }
        dirList.appendChild(el);
      });
    }

    function getDirContents(path) {
      return fakeFs[path] || [];
    }

    function isFolder(path, item) {
      const fullPath = path + item;
      return ["bin", "etc", "home", "usr", "var", "user"].includes(item) ||
             (path === "/" && item === "home") ||
             (fullPath === "/home/user/");
    }

    function navigateTo(newPath) {
      if (!fakeFs[newPath]) return;
      currentPath = newPath;
      document.getElementById("files-path").textContent = currentPath;
      document.getElementById("file-up").disabled = currentPath === "/";
      renderFsItems(currentPath);
    }

    document.getElementById("files-up").addEventListener("click", () => {
      if (currentPath !== "/") {
        const parentPath = currentPath.split("/").slice(0, -2).join("/") + "/";
        navigateTo(parentPath);
      }
    });

    // Notepad App Logic
    let notepadTabs = [];
    let activeTabIdx = 0;

    document.getElementById("new-tab").addEventListener("click", () => {
      const tabData = { title: "Untitled", content: "" };
      if (notepadTabs.length === 0) {
        notepadTabs.push(tabData);
      } else {
        notepadTabs.splice(1, 0, tabData);
        activeTabIdx = 1;
      }
      saveNotepad();
      renderTabs();
    });

    function loadNotepad() {
      const saved = localStorage.getItem("notepad");
      if (saved) {
        const data = JSON.parse(saved);
        notepadTabs = data.tabs;
        activeTabIdx = data.active;
        renderTabs();
        document.getElementById("editor").value = notepadTabs[activeTabIdx].content;
      } else {
        createDefaultTab();
      }
    }

    function saveNotepad() {
      localStorage.setItem("notepad", JSON.stringify({
        tabs: notepadTabs,
        active: activeTabIdx
      }));
    }

    document.getElementById("editor").addEventListener("input", () => {
      if (activeTabIdx < notepadTabs.length) {
        notepadTabs[activeTabIdx].content = document.getElementById("editor").value;
        saveNotepad();
      }
    });

    function renderTabs() {
      const tabsContainer = document.getElementById("tabs");
      tabsContainer.innerHTML = "";
      notepadTabs.forEach((tab, idx) => {
        const el = document.createElement("div");
        el.className = "tab";
        el.textContent = tab.title;
        if (idx === activeTabIdx) el.style.fontWeight = "bold";
        el.addEventListener("click", () => {
          activeTabIdx = idx;
          renderTabs();
          document.getElementById("editor").value = notepadTabs[idx].content;
          saveNotepad();
        });
        tabsContainer.appendChild(el);
      });
    }

    function createDefaultTab() {
      notepadTabs.push({ title: "Untitled", content: "" });
      activeTabIdx = 0;
      renderTabs();
      saveNotepad();
    }
  </script>
</body>
</html>
